runs.source:
// Rhino b95f75d: calling a static-looking Array method with no arguments (`Array.find()` — in
// Rhino Array.prototype methods are also reachable as Array.<name> generics) throws a raw Java
// ArrayIndexOutOfBoundsException past JS try/catch, in both modes, instead of a TypeError.
// Found by the jit1_function template run (templates_fz.py), 2026-10-18.
// Replay: oxpecker diff tests/regressions/array-find-no-args-aioobe-both-modes.js
try {
  Array.find();
} catch (e) {
  print("caught " + e);
}

// Rhino b95f75d: arrow functions get a `prototype` property in compiled mode. Per spec (and in
// the interpreter) arrows have none.
//   interpreted: "undefined"      compiled: "object"
// Found by replaying Rhino's own tests/testsrc/jstests/arrowfn.jstest (oxpecker corpus
// rhino-jstests), bisected to `assertEq(f.prototype, undefined)`, 2026-10-18.
// Replay: oxpecker diff tests/regressions/arrow-function-has-prototype-compiled.js
var f = () => 10;
__probe("p", typeof f.prototype, Object.getOwnPropertyNames(f));
typeof f.prototype;

// Rhino b95f75d: `CallSite` is a global constructor; an instance made by script has no stack
// element, and converting it to a string throws a Java NullPointerException out of the engine
// (NativeCallSite.js_toString -> ScriptStackElement.renderJavaStyle) in both modes, instead of a
// JS error. Found by the API generators (api_construct), 2026-10-18.
// Replay: oxpecker diff tests/regressions/callsite-tostring-npe-both-modes.js
var cs = new CallSite();
String(cs);

// Rhino b95f75d: in compiled mode a function local that is assigned the result of an operator the
// optimizer treats as always-numeric (unary -, ~, *, ++) is typed as a double; when the operands
// are BigInts, storing the result throws instead of keeping the BigInt:
//   function f() { var b = -1n; return b; }       interpreted: -1n    compiled: TypeError
//   function f(a) { var n = a * a; return n; }    f(10n): 100n vs TypeError: Cannot convert BigInt to a number
// Also `let`, `var b = ~1n`, `var n = 1n; n++`. Agrees: `var b = 1n` (no operator), `return -1n`
// (no local), top-level `var b = -1n`, `n = a + a` (+ is not assumed numeric).
// Generalises t262-bigint-to-number-overflow-throws.js (same root cause).
// Found by `oxpecker fuzz` (runs/fuzz-2026-10-19, hard-ca304333ca / hard-e91776e34c), 2026-10-19.
// Replay: oxpecker diff tests/regressions/compiled-bigint-in-number-typed-local.js
function f() { var b = -1n; return b; }
f();

// Rhino b95f75d: in compiled mode a relational comparison (<, <=, >, >=) between a function
// local or parameter and a number literal throws TypeError "Cannot convert BigInt to a number"
// when the variable holds a BigInt; the interpreter compares (1024n < 5 is false). Either operand
// order and a double literal (5.5) are affected. The literal's side can also be a local the
// optimizer types as a number (`const n = 5; v < n`), and the BigInt side can be a parameter, a
// local, or a captured top-level variable (`captured`). Agrees: ==, ===, a string literal ("5"),
// an untyped operand (a parameter `five`), and the same comparison at the top level. A try/catch
// inside the function also makes the modes agree (it forces an activation frame, so the variable
// is no longer a direct local), which is why the catch sits at the call site here.
// Not compiled-bigint-in-number-typed-local.js: no numeric operator touches the variable, a bare
// parameter compared with a literal is enough.
//   interpreted: the comparison's value ("false"/"true")   compiled: "TypeError" for lt, gt, leftLiteral, dbl, local, constLocal, captured
// Found by `oxpecker fuzz` (hour-long campaign, jit_tricky_function: `v10 = big1; return v10 < 5`
// in an arrow used as a do-while condition), 2026-10-27; the `const n` and captured forms came
// out of the 2026-10-28 campaign under the same coarse signature.
// Replay: oxpecker diff tests/regressions/compiled-bigint-relop-number-literal-local.js
function lt(v) { return v < 5; }
function gt(v) { return v > 5; }
function leftLiteral(v) { return 5 <= v; }
function dbl(v) { return v >= 5.5; }
function local() { var b = 1024n; return b < 5; }
function constLocal(v) { const n = 5; return v < n; }
var top = 1024n;
function captured() { return top < 5; }
function eq(v) { return v == 5; }
function noLiteral(v, five) { return v < five; }
function outcome(f, a, b) { try { return String(f(a, b)); } catch (e) { return e.name; } }
__probe("step", outcome(lt, 1024n), outcome(gt, 1024n), outcome(leftLiteral, 1024n), outcome(dbl, 1024n), outcome(local),
        outcome(constLocal, 1024n), outcome(captured), outcome(eq, 1024n), outcome(noLiteral, 1024n, 5), String(top < 5));

// Rhino b95f75d: compiled code passes the same boxed java.lang.Double instance for a numeric
// constant every time it is evaluated, the interpreter boxes a fresh one. A Java host function
// that returns its argument (J.echo, any identity-preserving embedder API) makes this visible to
// script as wrapper identity:
//   J.echo(3 + 1e21) === J.echo(3 + 1e21)    interpreted: false    compiled: true
// Java embedders comparing references (or using IdentityHashMap) see the same split.
// Found by `oxpecker fuzz` (runs/fuzz-2026-10-19, eight `@N[Java java.lang.Double]` signatures,
// e.g. hard-16b08c88ef), 2026-10-19.
// Replay: oxpecker diff tests/regressions/compiled-boxed-number-constant-identity.js
function f1() { return J.echo(3 + 1e21); }
function f2() { return J.echo(3 + 1e21); }
var a = f1(), b = f2();
__probe("p", a === b);
a === b;

// Rhino 1.9.2: a generator function whose body declares a `let` inside a block that may or may
// not run (an `if` with a non-constant condition, or a `while` body) and then yields after the
// block fails to compile: the bytecode generator throws IllegalStateException "bad local
// variable type: 0 at index: 7" for the whole script, so compiled mode crashes before running a
// line while the interpreter runs the generator normally. `const` instead of `let`, `var`, a
// constant condition (`if (true)`, folded away), the `yield` inside the block, `return` instead
// of `yield` after it, and the same shape in a plain function all agree. Same family as
// master-only/t262-yield-in-forof-catch-verifyerror.js (a `yield` from a `catch` inside `for-of`),
// which 1.9.2 compiles; not checked on master b95f75d.
//   interpreted: "function" | 1 | true     compiled: crash (IllegalStateException in Codegen)
// Found by `oxpecker fuzz` on 1.9.2 (first campaign after the switch, seed 13: a nested generator
// with `if (!b) { let x = ...; } else {} yield v`), 2026-10-28.
// Replay: oxpecker diff tests/regressions/compiled-generator-let-in-conditional-block-before-yield.js
function* g(c) { if (c) { let x = 1; } yield 1; }
var it = g(true);
__probe("step", typeof g, it.next().value, it.next().done);

// Rhino b95f75d: ++ and -- wrap at the int32 boundary in compiled mode when the target is not an
// optimizer-typed function local: top-level variables, locals of functions that need an activation
// (eval / arguments / with), object properties and array elements.
//   var n = 2147483647; n++;         interpreted: 2147483648     compiled: -2147483648
//   var n = -2147483648; n--;        interpreted: -2147483649    compiled: 2147483647
//   function f() { eval("1"); var n = 2147483647; return n++ + n; }   4294967295 vs -1
// `n += 1` and `n = n + 1` are correct; so is n++ inside a plain function (optimizer path).
// Found by the inspector export (activation_pair), reduced with variants in runs/inc, 2026-10-18.
// Replay: oxpecker diff tests/regressions/compiled-increment-int32-overflow.js
var n = 2147483647;
n++;
var m = -2147483648;
m--;
var o = {p: 2147483647};
o.p++;
__probe("p", n, m, o.p);
[n, m, o.p];

// Rhino b95f75d: compiled mode loses negative zero. A top-level variable holding a small
// integer is kept as an int by the optimizer, and `int * 0` cannot represent IEEE -0.
//   interpreted: -0 (spec)      compiled: 0        (Object.is(n * 0, -0): true vs false)
// Also: `var n = 0; n = ~n; n * 0`, `var n = 1; n = ~n; n * 0`. Agrees when n is a function
// local, when the value is constant-folded (`~0 * 0`), or when n comes from `-n - 1`.
// Found by the property test (tests/test_differential.py), shrunk by Hypothesis, 2026-10-18.
// Replay: oxpecker diff tests/regressions/compiled-negative-zero-lost-in-int-arith.js
var n = -1;
n * 0;

// Rhino b95f75d: a named property read through a Proxy (`p.x`, `p.length`) invokes the `has`
// trap before `get` in compiled mode; the interpreter (and the spec) call only `get`.
// Indexed reads (`p[1]`) agree. The compiled property-get linker apparently probes
// [[HasProperty]] first.
//   interpreted: ["get:x"]      compiled: ["has:x", "get:x"]
// Found by the jit templates run, confirmed with variants in runs/proxy, 2026-10-18.
// Replay: oxpecker diff tests/regressions/compiled-proxy-extra-has-trap-on-get.js
var log = [];
var p = new Proxy({}, {
  get(t, k, r) { log.push("get:" + String(k)); return Reflect.get(t, k, r); },
  has(t, k) { log.push("has:" + String(k)); return k in t; }
});
var x = p.x;
__probe("p", log);
log;

// Rhino b95f75d: calling a function that declares a (here unused) formal parameter, passing a
// relational-comparison expression (`1 < 2`) as the argument, from inside another function
// (not from top-level script code), makes the bytecode generator mis-track the operand stack
// depth: the JVM class verifier then rejects the generated method.
//   interpreted: ok (returns normally)
//   compiled:    java.lang.IllegalStateException: Stack underflow: -1
// Originating test: js1_8_1/trace/trace-test.js (`nestedExit`/`nestedExitLoop`, part of a large
// JIT-tracing mini-testsuite; `nestedExitLoop`'s call `nestedExit(j < 7)` is what crashes - the
// surrounding loops and the `if`/`++q` body are incidental).
// Found by replaying Rhino's legacy Mozilla suite (oxpecker corpus rhino-mozilla), 2026-10-18.
// Replay: oxpecker diff tests/regressions/compiled-relop-arg-stack-underflow.js --language-version 250
function a(x) {} function b() { a(1 < 2); }

// Rhino 1.9.2: in compiled mode a function with a rest parameter that is also called by name from
// inside another function (which makes it an optimizer direct-call target) binds the rest
// parameter to the first extra argument itself instead of an array of all the extra arguments.
// It then holds for every call of the function, not only the one inside the other function:
// top-level calls, `f.call(...)`, calls through an alias or a property. Extra arguments past the
// first are lost, a non-array argument arrives unwrapped (`rest === 7`), and an array argument
// arrives as the caller's own array, so `rest.length = 0` empties it. The interpreter, and the
// same function when no other function calls it (`k` below), build the array as the spec says.
//   interpreted: [7] | [7] | [7,8] | [7]      compiled: 7 | 7 | 7 | [7]
// Found by `oxpecker fuzz` on 1.9.2 (three-hour campaign, a helper with `...p20` called from a
// warmed function whose `p20.length = 0` emptied a global array), reduced by hand, 2026-11-01.
// Replay: oxpecker diff tests/regressions/compiled-rest-param-direct-call-target.js
function f(a, ...rest) { return rest; }
function g() { return f(0, 7); }
function k(a, ...rest) { return rest; }
__probe("step", f(0, 7), g(), f(0, 7, 8), k(0, 7));

// Rhino 1.9.2 and master b95f75d: in compiled mode an object-literal method that refers to
// `super` inside a block that also declares a `let` or `const` crashes at the super reference
// with a java.lang.ClassCastException the script cannot catch; the interpreter runs it
// normally. On 1.9.2 the message is "NativeWith cannot be cast to NativeCall" and only a super
// property *read* in such a block crashes (the `r` case); a super write (`w`) and a super method
// call (`c`) run. On master b95f75d it is "LocalScope cannot be cast to NativeCall" and all three
// crash. Both parts must share the block: `var` instead of `let`/`const`, the declaration in a
// sibling block, the super reference outside the block, and the same body without the block all
// agree. Class methods agree in both modes; strict mode and nesting the method in a function
// make no difference.
//   interpreted: "1" | "2" | "string"     compiled: crash (ClassCastException)
// Found by `oxpecker fuzz` on master (hour-long campaign, a super property assignment in a for
// loop whose body also declared a `const`), 2026-10-28.
// Replay: oxpecker diff tests/regressions/compiled-super-in-block-with-lexical-declaration-classcast.js
var w = { m() { { super.a = 1; const n = 0.1; return this.a; } } };
var r = { __proto__: { a: 2 }, m() { { let n = 0; return super.a; } } };
var c = { m() { { const n = 0; return typeof super.toString(); } } };
__probe("step", w.m(), r.m(), c.m());

// Rhino b95f75d: at script top level the compiled mode computes `x * 0` as +0 for a negative
// `x` held in a variable; the interpreter gives -0 (IEEE 754, and what the spec requires).
// Inside a function (`function f(p) { var y = p * 0; ... }`) both modes give -0, and a literal
// `-3 * 0` is folded to -0 by both. `Object.is(y, -0)` and `1 / y` show it.
//   interpreted: Object.is(y, -0) true,  1 / y -Infinity
//   compiled:    Object.is(y, -0) false, 1 / y Infinity
// Found by `oxpecker fuzz` (first ten-minute campaign, negative_zero / number_computation), 2026-10-26.
// Replay: oxpecker diff tests/regressions/compiled-top-level-multiply-by-zero-loses-sign.js
var x = -3;
var y = x * 0;
__probe("step", Object.is(y, -0), 1 / y, Object.is(x * 0, -0));

// Rhino 1.9.2: a `with` statement whose object is a LiveConnect wrapper of a Java object (the
// harness's `J`, a Java array such as `J.intArray(2)`, a Java string returned by a Java method)
// crashes the compiled mode at the first unqualified name read inside the block, whether the
// name is a member of the Java object (`sum`), a global (`Math`, `undefined`) or a `const` of
// the script: java.lang.ClassCastException "NativeJavaObject cannot be cast to
// ScriptableObject" (NativeJavaArray for arrays), thrown from the invokedynamic linker that
// folds `const` reads (ConstAwareLinker.getConstValue steps from the NativeWith to its prototype
// and casts it to ScriptableObject; the Java wrappers implement Scriptable directly). The script
// cannot catch it. The interpreter resolves the names normally. `typeof name` inside the block,
// a write (`name = 1`), a call (`f()` looks the callee up on another path) and an empty block
// agree; with an array the callee lookup throws TypeError in both modes before any argument is
// read, so `var x = length` is the array form. Not checked on master b95f75d.
//   interpreted: "function" | 1     compiled: crash (ClassCastException in ConstAwareLinker)
// Found by `oxpecker fuzz` on 1.9.2 (hour-long campaign, seed 15: `with (J) { v36 in Math; }`
// after lineage and source shrinking), 2026-10-28.
// Replay: oxpecker diff tests/regressions/compiled-with-java-object-name-lookup-classcast.js
with (J) {
    __probe("step", typeof sum, Math.abs(-1));
}

// Rhino b95f75d: inside a JS 1.7 generator function (implicit, from a bare `yield` in the body),
// using a parenthesized `yield` expression as a call argument (`z((yield 3))`) parses fine but
// the bytecode generator emits a stack frame the JVM verifier rejects:
//   interpreted: ok (generator created normally)
//   compiled:    java.lang.VerifyError: Bad type on operand stack
// Only the parenthesized form triggers it; `z(yield 3)` is a plain SyntaxError in both modes.
// Originating tests: js1_7/decompilation/regress-352026.js and
// js1_8_1/decompilation/regress-352026.js (both titled "decompilation of yield in argument
// lists", but the crash happens on ordinary compilation, no decompile/toString needed).
// Found by replaying Rhino's legacy Mozilla suite (oxpecker corpus rhino-mozilla), 2026-10-18.
// Replay: oxpecker diff tests/regressions/compiled-yield-call-arg-verifyerror.js --language-version 250
function g() { z((yield 3)); }

// Rhino b95f75d (master, 2.0.0-SNAPSHOT): a direct call to a top-level function that recurses
// returns the wrong value in compiled mode when the base case uses strict equality.
//   interpreted: 3      compiled: 1
// Triggers with `n === 0`; `n == 0`, `n <= 0` and `n < 1` agree between modes. Disappears when
// the call is not a direct call (var r = function…, or via a local alias t = r).
// Found by hand while smoke-testing the harness, characterised with runs of variants, 2026-10-18.
// Replay: oxpecker diff tests/regressions/direct-recursive-call-completion.js
function r(n) { return n === 0 ? 0 : r(n - 1) + 1; }
r(3);

// Rhino b95f75d: `Error.prototype.toSource.call(null)` throws a raw Java NullPointerException
// ("Cannot invoke Scriptable.get(...) because obj is null") past JS try/catch in both modes,
// instead of a TypeError. `.call(undefined)` is fine.
// Found by `oxpecker fuzz` (runs/fuzz-2026-10-19, hard-9266ec7b04), 2026-10-19.
// Replay: oxpecker diff tests/regressions/error-tosource-null-npe-both-modes.js
try {
  Error.prototype.toSource.call(null);
} catch (e) {
  print("caught " + e);
}

// Rhino b95f75d: update expressions through a computed super reference are wrong in the
// interpreter. `++super[k]` evaluates to the *key* ("p") instead of 2, and `super[k]--` leaves an
// own property "0" with value "p" on the receiver. Compiled mode is correct. Same area as the
// test262 case Rhino tags interpreted-only (prop-expr-getsuperbase-before-topropertykey-...).
//   interpreted: ["p", ...own "0": "p"]      compiled: [2, ...]
// Found by the inspector export (super_in_object_literal), minimised by hand, 2026-10-18.
// Replay: oxpecker diff tests/regressions/interpreted-computed-super-update.js
var proto = {p: 1};
var o = {
  __proto__: proto,
  inc(k) { return ++super[k]; },
  dec(k) { return super[k]--; }
};
var r1 = o.inc("p");
var r2 = o.dec("p");
__probe("p", r1, r2, Object.getOwnPropertyNames(o), proto.p, o.p);
[r1, r2];

// Rhino b95f75d: `super.x++` where the inherited value is a string does string concatenation in
// the interpreter ("a" -> "a1") instead of ToNumber ("a" -> NaN, as compiled mode does).
// Related to tests/regressions/interpreted-computed-super-update.js (++super[k] returns the key).
//   interpreted: "a1"      compiled: NaN
// Found by the property test (tests/test_differential.py), 2026-10-18.
// Replay: oxpecker diff tests/regressions/interpreted-super-increment-string-concat.js
var proto = {x: "a"};
var o = {
  __proto__: proto,
  upd() { super.x++; return this.x; }
};
var r = o.upd();
__probe("p", r, o.x, proto.x);
r;

// Rhino 1.9.2: the `__proto__` accessor on a LiveConnect wrapper of a Java array (`J.intArray(2)`)
// crashes both modes with java.lang.ClassCastException "NativeJavaArray cannot be cast to
// ScriptableObject", which the script cannot catch: writing `a.__proto__ = {}` fails in
// NativeObject.js_protoSetter; `Object.setPrototypeOf(a, {})` itself succeeds, but a later read of
// `a.__proto__` fails in NativeObject.js_protoGetter. The wrapper of a plain Java object
// (`J.__proto__ = {}`) throws a catchable InternalError instead. The fuzzer's forms set the array's prototype to itself or to a JS array
// built from it. Same cast family as compiled-with-java-object-name-lookup-classcast.js (Java
// wrappers implement Scriptable directly, not ScriptableObject). Not checked on master b95f75d.
//   interpreted: crash (ClassCastException)     compiled: crash (ClassCastException)
// Found by `oxpecker fuzz` on 1.9.2 (three-hour campaign: `o8.__proto__ = v9` with `v9` the same
// Java array, and with an array of its length/type/sum), 2026-11-01.
// Replay: oxpecker diff tests/regressions/java-array-set-prototype-classcast.js
var a = J.intArray(2);
var r = [];
try { a.__proto__ = {}; r.push("ok"); } catch (e) { r.push(e.name); }
__probe("step", r);

// oxpecker-expect: java-types
// Rhino b95f75d: the same JS number reaches a Java host function as java.lang.Double from the
// interpreter but as java.lang.Integer from compiled code. Pure JS behaviour is identical; a Java
// embedder casting the result (e.g. `(Integer) r`) sees the difference.
//   interpreted trace javaTypes: String | Double | Double      compiled: String | Double | Integer
// Replay: bin/harness --replay tests/regressions/java-int-literal-double-vs-integer.js
function f(a) { var i = 0; i = a + 1; return i; }
__probe("p", f(1), 7);
f(2);

// Rhino 1.9.2: a labelled `for` (or `for-in`) whose head holds a function containing a loop,
// with a `continue` naming the label in the body, is miscompiled in both modes. Compiled code
// does not compile: Codegen throws RuntimeException "unlocated label" for the whole script, so
// it crashes before running a line. The interpreter runs, but `continue L` jumps past the
// loop's update (`i++`), so the loop never ends (the guard below stops it at five rounds); with
// `for (;;) { break; }` as the inner loop its CodeGenerator fails an assertion instead
// (IllegalStateException "FAILED ASSERTION"). The label, `continue L` (not `break L`, not a bare
// `continue`), the function in the head and the loop inside it are all needed; a `while`
// condition holding the same function, or the function in the body, compile and run correctly.
// The inner loop apparently takes over the label's continue target.
//   interpreted: [0,0,0,0,0]      compiled: crash (RuntimeException: unlocated label)
//   spec: [0,1]
// Found by `oxpecker fuzz` on 1.9.2 (seeded three-hour campaign: `continue L85` in a
// `for (let [a, b] = (() => { ... for (let i ...) {} ... })(); ...)`), reduced by hand, 2026-11-02.
// Replay: oxpecker diff tests/regressions/labelled-for-head-function-loop-continue.js
var r = [];
L: for (var a = function () { while (false) {} }, i = 0; i < 2; i++) {
    r.push(i);
    if (r.length > 4) break;
    continue L;
}
__probe("step", r);

// Rhino b95f75d: a `switch` case value that is a JS 1.7 generator expression whose per-element
// expression is a `let (...) expr` parses in a way that leaves the parser's TokenStream (`this.ts`)
// null when some later parse step reads it back, crashing the engine instead of reporting a
// syntax error (E4X and nested comprehensions are not required - this is just `let` + a genexpr
// used as a `case` value):
//   interpreted: java.lang.NullPointerException: Cannot read field "cursor" because "this.ts" is null
//   compiled:    java.lang.NullPointerException: Cannot read field "cursor" because "this.ts" is null
// Originating tests: js1_7/regress/regress-352870-01.js and js1_7/regress/regress-352870-02.js
// (both combine this with E4X and nested array comprehensions, which are incidental).
// Found by replaying Rhino's legacy Mozilla suite (oxpecker corpus rhino-mozilla), 2026-10-18.
// Replay: oxpecker diff tests/regressions/let-genexpr-switch-case-null-tokenstream.js --language-version 250
switch (0) { case (let (a) 0 for (c in 0)): }

// Rhino b95f75d: repeated self-concatenation (`s += s`) doubles a string's length every
// iteration; once the length hits exactly 2^31 the internal char-array allocation overflows
// to Integer.MIN_VALUE and both evaluators throw a raw Java NegativeArraySizeException instead
// of an `Error` (e.g. a RangeError or OutOfMemoryError) a script could catch:
//   interpreted: java.lang.NegativeArraySizeException: -2147483648
//   compiled:    java.lang.NegativeArraySizeException: -2147483648
// Originating test: js1_5/Regress/regress-3649-n.js (doubles a 4-char string 100000 times;
// here a 1-char seed and 31 doublings hit the exact 2^31 boundary much faster).
// Found by replaying Rhino's legacy Mozilla suite (oxpecker corpus rhino-mozilla), 2026-10-18.
// Replay: oxpecker diff tests/regressions/string-doubling-overflow-negative-array-size.js --language-version 250
var s = "a"; for (var i = 0; i < 31; i++) s += s;

// Rhino 1.9.2 and master b95f75d: a compound assignment to a super property in an object-literal
// method reads the property with the wrong receiver in the interpreted mode: the getter runs
// with `this` = the prototype instead of the instance. The compiled mode passes the instance,
// as the spec requires (super property access uses the current `this` as receiver). A plain
// read (`super.g`) and an explicit `var x = super.g; x += 1` agree in both modes, so only the
// compound path is affected. With a typed array as the prototype, `super.length += 1` therefore
// runs in the interpreter and throws TypeError in compiled code (the accessor rejects a plain
// object as `this`). With `super.__proto__ **= 3` and an array prototype whose `toString` is
// not callable, the compiled mode reads the array through the instance and ToPrimitive throws
// (correct); the interpreter reads Array.prototype through the prototype and converts it
// quietly. The form found on master, `super.__proto__ /= 10` with a Date prototype
// (interpreted TypeError '"this" is not an instance of class NativeDate'), does not show on 1.9.2.
